// Lehnt Nachrichten ohne korrekte Provenienz/Korrelation ab.
const body = $input.first().json.body ?? {};
if (body.external_origin !== 'n8n') {
  throw new Error('external_origin must be n8n');
}
if (!body.correlation_id || !body.event_id) {
  throw new Error('correlation_id and event_id are required');
}
return [{ json: body }];
